#!/bin/bash
# KADIMA NIFTY 50 breadth SHADOW (PR #49, commit 63946ddcbaeb59014cccae6f7358733601ffdb9a). Never changes a forecast.
# Needs PR #48 live (hourly_forecast.py 16b92751). Run on EC2 after 15:45 IST.
#   bash deploy_nifty_breadth_shadow_20261020.sh             # backup, install, restart, health check
#   bash deploy_nifty_breadth_shadow_20261020.sh --rollback  # restore #48 file, remove module, restart
set -u
ROOT=${KADIMA_ROOT:-$HOME/kadima-py}
F=$ROOT/kadima/hourly_forecast.py; M=$ROOT/kadima/nifty_breadth.py
BASE=16b92751a7a1dfc024ac09fdeaa4fb7759943b587452e98912968e64022598e8
NEW=85b70cb8d71d446db214d4f84d69f07e253b9fba1cabc5b6a2c23ddee7cf32a2
MODSHA=50abc24f2ff0e61d44cc4bda14063032e4687a9122263addf867a7d27b7ee2a4
BAK=$F.bak-breadth-20261020
h() { sha256sum "$1" | cut -c1-64; }
health() {
  sleep 25
  systemctl is-active --quiet kadima || { echo "HEALTH FAIL: kadima not active"; return 1; }
  if journalctl -u kadima --since "-1 min" --no-pager | grep -q "Traceback"; then echo "HEALTH FAIL: traceback"; return 1; fi
  echo "health ok"; return 0
}
if [ "${1:-}" = "--rollback" ]; then
  [ "$(h $BAK)" = "$BASE" ] || { echo "ABORT: backup missing or wrong hash"; exit 1; }
  cp -p "$BAK" "$F" && rm -f "$M" && sudo systemctl restart kadima && health; echo "live hash $(h $F | cut -c1-12) (PR #48 16b92751a7a1)"; exit
fi
echo "== 1. gates"
CUR=$(h $F); echo "live ${CUR:0:12} base ${BASE:0:12} release ${NEW:0:12}"
[ "$CUR" = "$NEW" ] && [ -f "$M" ] && [ "$(h $M)" = "$MODSHA" ] && { echo "already installed"; exit 0; }
[ "$CUR" = "$BASE" ] || { echo "ABORT: live file is not the PR #48 release; nothing changed"; exit 1; }
HM=$(TZ=Asia/Kolkata date +%H%M); DOW=$(TZ=Asia/Kolkata date +%u)
if [ "$DOW" -le 5 ] && [ "$HM" -ge 0900 ] && [ "$HM" -lt 1545 ]; then echo "ABORT: market hours (IST $HM); run after 15:45"; exit 1; fi
read -r -p "No open positions and OK to restart kadima now? type YES: " OK; [ "$OK" = "YES" ] || { echo "stopped, nothing changed"; exit 1; }
echo "== 2. backup"
cp -p "$F" "$BAK"; echo "backup $(h $BAK | cut -c1-12) -> $BAK"
echo "== 3. install"
echo '' | base64 -d > "$F.new-breadth"; echo '' | base64 -d > "$M.new"
[ "$(h $F.new-breadth)" = "$NEW" ] && [ "$(h $M.new)" = "$MODSHA" ] || { rm -f "$F.new-breadth" "$M.new"; echo "ABORT: payload hash mismatch"; exit 1; }
$ROOT/venv/bin/python -m py_compile "$F.new-breadth" && $ROOT/venv/bin/python -m py_compile "$M.new" || { rm -f "$F.new-breadth" "$M.new"; echo "ABORT: does not compile"; exit 1; }
mv "$M.new" "$M"; mv "$F.new-breadth" "$F"; echo "installed $(h $F | cut -c1-12) + nifty_breadth $(h $M | cut -c1-12) (shadow)"
echo "== 4. restart + health"
sudo systemctl restart kadima
if ! health; then echo "== AUTO ROLLBACK"; cp -p "$BAK" "$F"; rm -f "$M"; sudo systemctl restart kadima; health; echo "rolled back to $(h $F | cut -c1-12)"; exit 1; fi
DD=$(systemctl show kadima -p Environment --value | tr ' ' '\n' | grep '^KADIMA_DATA_DIR=' | cut -d= -f2); DD=${DD:-/var/lib/kadima}
[ -f "$DD/nifty50_weights.json" ] && echo "weights file present" || echo "NOTE: $DD/nifty50_weights.json missing -> nothing is recorded until it is added (no restart needed)"
free -m | head -3
echo "DONE: breadth shadow ${NEW:0:12} live. Rollback: bash $0 --rollback"
